Item.method_code:
/*
    改訂の実施
        対象：帳票マスタ・開達書式
        
        1. 改訂ダイアログを開く
        2. ダイアログの入力欄に入力してもらう
        3. OKで改定処理開始
        
    マルQページ作成
        ・マルQページ作成処理。
        ・マルQページ検索グリッド上のコマンドバーボタンからのトリガーを想定。
        ・特定の室課マスタを選択し、マルQページとして複製する。
*/

const iomInv = aras.IomInnovator;
const targetType = this.itemTypeName;
const parentItem = parent.thisItem;
var thisItemID = thisItem.getID();
var thisItemType = thisItem.getType();

// アイコンを処理実行中に変更
aras.browserHelper.toggleSpinner(parent.document, true);    

// 表示するラベルを取得する
var dialog_title = getUserMessageText("h4_C_I_0003");

// 無名async関数による非同期処理の即時実行
(async (thisItem) => 
{
    // 値設定ダイアログ生成
    var form = aras.getFormForDisplay(aras.getFormId('h4_RevisioDialog'));
    var topWnd = top.aras.getMostTopWindowWithAras();
    var wnd = topWnd ? topWnd : window;

    var params = {
        title: dialog_title,
        formId: form.node.getAttribute('id'),
        dialogWidth: 550,
        dialogHeight: 380,
        mode: 'edit',
        content: 'ShowFormAsADialog.html'
    };


    topWnd.ArasModules.MaximazableDialog.show('iframe', params).promise.then(function(dlgRes) 
    {
        if (!dlgRes) 
        {
            return;//キャンセル
        }


        //0：確認事項  1:改定理由  2:すぐに公開チェック
        var results = dlgRes.split(',');
        if(results[0] == "" || results[1] == "")
        {
            aras.AlertError("katotest 必須項目に入力が必要");//メッセージ作る
        }


        //共通処理
        // 改訂履歴アイテムを生成し、親アイテムに紐づける
        //サーバーメソッドを呼んで、改訂履歴アイテムの作成と紐づけを行う
        var result = iomInv.newItem("Method", "h4_StartRevision");
        result.setProperty("id", thisItemID);
        result.setProperty("type", thisItemType);
        result.setProperty("revision_summary", results[0]);//確認事項
        result.setProperty("revision_reason", results[1]);//改定理由
        result.setProperty("isPromoteNow", results[2]);//すぐに更新チェック "on/off"
        result = result.apply();
        
        debugger;
        if(result.isError())
        {
            aras.AlertError(result.getErrorString());
            return;
        }
        
        
        //承認を回して改訂の場合リビジョンアップ＋画面更新（ただし、レスポンシブフォームなので不完全）
        if(results[2] == "false")//文字で返ってくる
        {
            parentItem.setAttribute("action", "h4_CreateNewRevision");
            const createNewRevisionResponse = aras.soapSend('ApplyMethod', parentItem.node.xml);
            if (createNewRevisionResponse.getFaultCode() !== 0) {
                aras.AlertError(createNewRevisionResponse);
                return;
            }
            
            debugger;
            
            const createNewRevisionResult = createNewRevisionResponse.getResultsBody();
            const dom = aras.createXMLDocument();
            dom.loadXML(createNewRevisionResult);
            
            aras.uiReShowItemEx(parent.itemID, dom.documentElement, parent.viewMode);   
        }
        parent.onRefresh();
    });
})(thisItem);

aras.browserHelper.toggleSpinner(parent.document, false);
return;

function getUserMessageText(name) {
    var userMsgItem = iomInv.newItem("UserMessage", "get");
    userMsgItem.setAttribute("select", "text");
    userMsgItem.setProperty("name", name);
    userMsgItem = userMsgItem.apply();
    var msg = userMsgItem.getProperty("text", "");
    return msg;
}
